import sys; sys.path.insert(0, sys.argv[1])
from body import *
def lst(paths, indent):
    return ",\n".join(f'{indent}"{d}"' for d in full(paths))
def region_map(regions):
    out = []
    for m, ps in regions.items():
        out.append(f"        Muscle.{m} to listOf(\n{lst(ps, '            ')},\n        ),")
    return "\n".join(out)
src = f'''package com.chdjalil.jalilgym.core.ui.body

import com.chdjalil.jalilgym.core.model.Muscle

// GENERATED by tools/heatmap/body_kotlin.py from tools/heatmap/body.py — do not edit by hand.
// Original, simplified artwork made for Jalilgym.
// One figure is 100 x 200 units; the head is drawn separately as a circle.

internal object BodyArtwork {{
    const val VIEWPORT_WIDTH = 100f
    const val VIEWPORT_HEIGHT = 200f
    const val HEAD_CENTER_X = 50f
    const val HEAD_CENTER_Y = 13f
    const val HEAD_RADIUS = 9f

    val silhouette: List<String> = listOf(
{lst([SILHOUETTE], '        ')},
    )

    val front: Map<Muscle, List<String>> = mapOf(
{region_map(FRONT)}
    )

    val back: Map<Muscle, List<String>> = mapOf(
{region_map(BACK)}
    )
}}
'''
src = src.replace("100", "100")
open(sys.argv[2], "w").write(src)
